use aes::{cipher::{BlockCipherEncrypt, KeyInit}, Aes128};
use zeroize::Zeroizing;
mod baseline;
mod sbox_inline;
mod hot_inline;
fn fill(bytes: &mut [u8], seed: &mut u32) {
    for word in bytes.chunks_mut(4) {
        *seed ^= *seed << 13;
        *seed ^= *seed >> 17;
        *seed ^= *seed << 5;
        word.copy_from_slice(&seed.to_le_bytes());
    }
}
macro_rules! measure_cipher {
    ($name:ident, $module:ident) => {
        #[no_mangle]
        pub extern "C" fn $name(rounds: u32, mut seed: u32, verify: u32) -> u32 {
            let mut key = [0u8; 16];
            fill(&mut key, &mut seed);
            let cipher = $module::FourBlockAes128::new(&key);
            let reference = Aes128::new(&key.into());
            let mut checksum = 0u32;
            for _ in 0..rounds {
                let mut batch = Zeroizing::new($module::FourBlocks::default());
                for block in &mut batch.0 { fill(block, &mut seed); }
                let mut expected = Zeroizing::new([aes::cipher::Block::<Aes128>::default(); 4]);
                if verify != 0 {
                    for (dst, src) in expected.iter_mut().zip(&batch.0) { dst.copy_from_slice(src); }
                    reference.encrypt_blocks(&mut expected[..]);
                }
                cipher.encrypt_four(&mut batch);
                for (block, expected) in batch.0.iter().zip(expected.iter()) {
                    for (&byte, &reference) in block.iter().zip(expected.iter()) {
                        if verify != 0 { assert_eq!(byte, reference); }
                        checksum = checksum.wrapping_mul(31).wrapping_add(u32::from(byte));
                    }
                }
            }
            core::hint::black_box(checksum)
        }
    };
}
measure_cipher!(baseline_cipher, baseline);
measure_cipher!(sbox_inline_cipher, sbox_inline);
measure_cipher!(hot_inline_cipher, hot_inline);
